#[export] Program Instance FinSet_Classifier :
  @SubobjectClassifier FinSet FinSet_Terminal := {|
  Ω     := 2%nat;
  truth := fun _ => fin_true;
  char  := fun u x (m : u ~{FinSet}~> x) (_ : Monic m) (b : Fin.t x) =>
    fin_of_bool (fin_existsb (fun a => fin_eqb (m a) b))
|}.   (* obligations discharged: char_pullback -- 'u is the preimage of fin_true under char m' -- and char_unique *)

Theorem sets_char_pullback@{o so sso} {A B : SetoidObject@{o o}}
  (m : A ~{Sets@{o so}}~> B) (Hm : @Monic Sets@{o so} A B m) :
  @IsPullback Sets@{so sso}
    (Setoid_Lift@{o so} B) unit_setoid_object@{so so} PropSetoid@{o so}
    (char_setoid@{o so} m) sets_true@{o so}
    (Setoid_Lift@{o so} A)
    (SetoidMorphism_Lift@{o so} m) sets_to_unit@{so}.

Theorem sets_char_subobject@{o so} {A B : SetoidObject@{o o}}
  (m : A ~{Sets@{o so}}~> B) (Hm : @Monic Sets@{o so} A B m) :
  @equiv _ (@SubObj_Setoid Sets@{o so} B)
    (@Build_SubObj Sets@{o so} B A m Hm)
    (@Build_SubObj Sets@{o so} B (Sets_Image m) (Sets_Image_mono m)
       (Sets_Image_mono_monic m)).   (* the pullback APEX, unlike Ω, stays at one level *)

Record IsPullback {C : Category} {x y z : C} (f : x ~> z) (g : y ~> z)
       (P : C) (p1 : P ~> x) (p2 : P ~> y) := {
  is_pullback_commutes : f ∘ p1 ≈ g ∘ p2;
  is_pullback_ump : ∀ Q (q1 : Q ~> x) (q2 : Q ~> y), f ∘ q1 ≈ g ∘ q2
    → ∃! u : Q ~> P, p1 ∘ u ≈ q1 ∧ p2 ∘ u ≈ q2
}.   (* a genuine pullback: commuting square plus the full universal property *)

Class ElementaryTopos (C : Category) := {
  topos_terminal   : @Terminal C;
  topos_cartesian  : @Cartesian C;
  topos_pullbacks  : @HasPullbacks C;
  topos_closed     : @Closed C topos_cartesian;
  topos_classifier : @SubobjectClassifier C topos_terminal
}.

Class Closed := {
  exponent_obj : obj → obj → obj  where "y ^ x" := (exponent_obj x y);
  (* The product-exponential adjunction (- × y) ⊣ (- ^ y), as the natural
     isomorphism Hom(x × y, z) ≅ Hom(x, z^y). *)
  exp_iso {x y z} : x × y ~> z ≊ x ~> z^y;
  ...
  ump_exponents' {x y z} (f : x × y ~> z) : eval' ∘ first (@curry' _ _ _ f) ≈ f
}.

Definition FinSet_Topos : ElementaryTopos FinSet := {|
  topos_terminal   := FinSet_Terminal;
  topos_cartesian  := FinSet_Cartesian;
  topos_pullbacks  := FinSet_Pullbacks;
  topos_closed     := FinSet_Closed;
  topos_classifier := FinSet_Classifier
|}.
